const API_BASE = process.env.REACT_APP_API_URL;

const API = axios.create({
  baseURL: API_BASE,
  timeout: 10000,
  headers: { "Content-Type": "application/json" },
});

API.interceptors.response.use(
  (res) => res,
  (err) => {
    console.error("API Error:", err?.response || err.message);
    return Promise.reject(err);
  }
);

module.exports = {
  fetchIncidents: (params) => API.get("/incidents", { params }),
  fetchIncidentById: (id) => API.get(`/incidents/${id}`),
  createIncident: (data) => API.post("/incidents", data),
  updateIncidentStatus: (id, status) => API.patch(`/incidents/${id}/status`, { status }),
  addIncidentComment: (id, text) => API.post(`/incidents/${id}/comments`, { text }),
};

// ------------------ API Functions ------------------

// Fetch all incidents
export const fetchIncidents = (params) => API.get("/incidents", { params });

// Fetch incident by ID
export const fetchIncidentById = (id) => API.get(`/incidents/${id}`);

// Create a new incident
export const createIncident = (data) => API.post("/incidents", data);

// Update incident status
export const updateIncidentStatus = (id, status) =>
  API.patch(`/incidents/${id}/status`, { status });

// Add a comment
export const addIncidentComment = (id, text) =>
  API.post(`/incidents/${id}/comments`, { text });
